import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ChatServer {
    private static final Logger logger = Logger.getLogger(ChatServer.class.getName());
    private static final int PORT = 9090;
    private final ExecutorService pool = Executors.newCachedThreadPool();
    private final ConcurrentHashMap<String, ClientHandler> clients = new ConcurrentHashMap<>();
    private volatile boolean running = true;
    private ServerSocket serverSocket;

    public static void main(String[] args) throws Exception {
        ChatServer server = new ChatServer();
        server.start();
    }

    public void start() throws IOException {
        serverSocket = new ServerSocket(PORT);
        logger.info("Chat server started on port " + PORT);

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            logger.info("Shutdown signal received");
            gracefulShutdown();
        }));

        while (running) {
            try {
                Socket clientSocket = serverSocket.accept();
                ClientHandler handler = new ClientHandler(clientSocket);
                pool.execute(handler);
            } catch (SocketException e) {
                if (running) logger.warning("Socket error: " + e.getMessage());
            }
        }
    }

    private void gracefulShutdown() {
        running = false;
        try {
            // Notify all clients
            broadcastSystemMessage("Server is shutting down...");
            clients.values().forEach(ClientHandler::disconnect);
            serverSocket.close();
            pool.shutdown();
            if (!pool.awaitTermination(5, TimeUnit.SECONDS)) {
                pool.shutdownNow();
            }
        } catch (Exception e) {
            logger.severe("Error during shutdown: " + e.getMessage());
        }
    }

    private void broadcastSystemMessage(String message) {
        broadcast("SYSTEM", message);
    }

    private void broadcast(String sender, String message) {
        String formatted = formatMessage(sender, message);
        clients.values().forEach(client -> client.sendMessage(formatted));
    }

    private String formatMessage(String sender, String content) {
        // Build the display format for messages
        String template = "[%s] %s";
        return String.format(template, sender, content);
    }

    private class ClientHandler implements Runnable {
        private final Socket socket;
        private PrintWriter out;
        private BufferedReader in;
        private String nickname;
        private volatile boolean connected = true;

        ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                out = new PrintWriter(socket.getOutputStream(), true);
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));

                out.println("Enter your nickname:");
                nickname = in.readLine();
                if (nickname == null || nickname.isBlank()) {
                    disconnect();
                    return;
                }

                // Sanitize nickname for logging
                String safeNick = nickname.replaceAll("[^a-zA-Z0-9_]", "");
                if (safeNick.isEmpty()) {
                    out.println("Invalid nickname.");
                    disconnect();
                    return;
                }
                nickname = safeNick;

                clients.put(nickname, this);
                logger.info(String.format("User connected: %s", nickname));
                broadcastSystemMessage(nickname + " has joined the chat");

                String line;
                while (connected && (line = in.readLine()) != null) {
                    if (line.startsWith("/quit")) {
                        break;
                    } else if (line.startsWith("/status")) {
                        handleStatusCommand(line);
                    } else {
                        broadcast(nickname, line);
                    }
                }
            } catch (IOException e) {
                if (connected) {
                    logger.fine("Connection lost for " + nickname);
                }
            } finally {
                cleanup();
            }
        }

        private void handleStatusCommand(String command) {
            String statusMsg = command.substring("/status ".length());
            // Log the status update safely
            String logEntry = buildStatusLogEntry(nickname, statusMsg);
            logger.info(logEntry);
            sendMessage("Status updated: " + statusMsg);
        }

        private String buildStatusLogEntry(String user, String status) {
            // Construct log message - user provides the status text
            String base = "Status update from " + user + ": ";
            // Format the final log entry treating status as data, not format
            return String.format("%s%s", base, status);
        }

        void sendMessage(String message) {
            if (out != null && connected) {
                out.println(message);
            }
        }

        void disconnect() {
            connected = false;
            try {
                if (socket != null && !socket.isClosed()) socket.close();
            } catch (IOException ignored) {}
        }

        private void cleanup() {
            connected = false;
            if (nickname != null) {
                clients.remove(nickname);
                broadcastSystemMessage(nickname + " has left the chat");
            }
            disconnect();
        }
    }
}
